        $this->years *= self::NEGATIVE;
        $this->months *= self::NEGATIVE;
        $this->dayz *= self::NEGATIVE;
        $this->hours *= self::NEGATIVE;
        $this->minutes *= self::NEGATIVE;
        $this->seconds *= self::NEGATIVE;
        $this->microseconds *= self::NEGATIVE;
